test('renderInvoiceText VAT is calculated on net amount after discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }], // €850 - €85 = €765, VAT €160.65
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /Subtotal: €850\.00/);
