});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 10, unitPrice: 9500 },
      { qty: 3, unitPrice: 6000 },
    ],
  };
  const totals = invoiceTotals(invoice);
