test('invoiceTotals with no lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 0, discount: 0, total: 0 });
});

test('invoiceTotals uses lineTotal function', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 120000 },
      { qty: 1, unitPrice: 980 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, lineTotal(invoice.lines[0]) + lineTotal(invoice.lines[1]));
  assert.equal(totals.total, totals.subtotal);
