});

test('invoiceTotals calculates VAT after discount per line', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 }, // €850 - €85 = €765, VAT €160.65
      { sku: 'PRINT-A4', qty: 100 }, // €37, VAT €3.33
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000 + 3700);
  assert.equal(totals.discount, 8500);
  const expectedVAT = 16065 + 333;
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, 88700 - 8500 + expectedVAT);
});

test('invoiceTotals total formula: subtotal - discount + vat', () => {
  const invoice = createInvoice({
    customerId: 'C-003', // silver tier (2.5%)
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // €425, discount 2.5% = €10.625, net €414.375, VAT €87.02
      { sku: 'LOGO-PACK', qty: 2, discountPercent: 10 }, // €2400, discount 10% = €240, net €2160, VAT €453.60
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 42500 + 240000;
  const expectedDiscount = 1063 + 24000; // rounded per line
  const expectedVAT = 8702 + 45360; // rounded per line
  const expectedTotal = expectedSubtotal - expectedDiscount + expectedVAT;

  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, expectedTotal);
});

test('invoiceTotals total is clamped at 0 after VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 100 }, // €600 - €600 = €0 + VAT (0%)
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, 0);
});

