import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, lineDiscount, lineVAT } from '../src/invoices.js';
import { TIER_DISCOUNTS } from '../src/customers.js';

test('createInvoice creates a draft invoice with valid data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2025-10-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);

  const line = result.value.lines[0];
  assert.equal(line.sku, 'DES-HOUR');
  assert.equal(line.name, 'Design work (hour)');
  assert.equal(line.qty, 5);
  assert.equal(line.unitPrice, 8500);
  assert.equal(line.vatRate, 21);
});

test('createInvoice handles multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-01',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'COPY-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);
  assert.equal(result.value.lines[0].name, 'Development (hour)');
  assert.equal(result.value.lines[1].name, 'Copywriting (hour)');
  assert.equal(result.value.lines[2].name, 'Icon set (24 icons)');
});

test('createInvoice reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('createInvoice reports DATE_INVALID for bad date format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '15-10-2025',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports DATE_INVALID for invalid date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports NO_LINES for empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-15',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports NO_LINES for missing lines', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-15',
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports QTY_INVALID for zero quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports QTY_INVALID for negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-15',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports QTY_INVALID for fractional quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 2.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports UNKNOWN_SKU for invalid SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-15',
      lines: [{ sku: 'INVALID-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice stops at first error in lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'BAD-SKU', qty: 1 },
      { sku: 'DEV-HOUR', qty: 0 },
    ],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice copies product data, not references', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const line = result.value.lines[0];
  assert.equal(line.name, 'Logo package');
  assert.equal(line.unitPrice, 120000);
  assert.equal(line.vatRate, 21);
});

test('createInvoice handles VAT-exempt products', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const line = result.value.lines[0];
  assert.equal(line.vatRate, 0);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { qty: 5, unitPrice: 8500 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal handles different quantities', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 1000 }), 1000);
  assert.equal(lineTotal({ qty: 10, unitPrice: 500 }), 5000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 8925);
  assert.equal(totals.total, 51425);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, vatRate: 21 },
      { qty: 10, unitPrice: 9500, vatRate: 21 },
      { qty: 3, unitPrice: 6000, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 5 * 8500 + 10 * 9500 + 3 * 6000;
  const expectedVAT = 8925 + 19950 + 1620;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, expectedSubtotal + expectedVAT);
});

test('invoiceTotals with no lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 0, discount: 0, vat: 0, total: 0 });
});

test('invoiceTotals uses lineTotal function', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 120000, vatRate: 21 },
      { qty: 1, unitPrice: 980, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, lineTotal(invoice.lines[0]) + lineTotal(invoice.lines[1]));
  assert.ok(totals.vat > 0);
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('addLine adds a new line to an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].qty, 3);
  assert.equal(result.value.lines[1].name, 'Development (hour)');
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].qty, 8);
});

test('addLine validates qty like createInvoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: -5 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 2.5 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine validates SKU like createInvoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'INVALID-SKU', qty: 5 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine refuses to change non-draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const nonDraftInvoice = { ...invoice, status: 'sent' };
  assert.deepEqual(addLine(nonDraftInvoice, { sku: 'DEV-HOUR', qty: 5 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const originalLineCount = invoice.lines.length;
  const originalQty = invoice.lines[0].qty;

  addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });

  assert.equal(invoice.lines.length, originalLineCount);
  assert.equal(invoice.lines[0].qty, originalQty);
});

test('removeLine removes a line by SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  }).value;

  const result = removeLine(invoice, 'DEV-HOUR');
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[1].sku, 'COPY-HOUR');
});

test('removeLine reports LINE_NOT_FOUND for non-existent SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  assert.deepEqual(removeLine(invoice, 'INVALID-SKU'), { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES when removing the last line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), { ok: false, error: 'NO_LINES' });
});

test('removeLine refuses to change non-draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;

  const nonDraftInvoice = { ...invoice, status: 'sent' };
  assert.deepEqual(removeLine(nonDraftInvoice, 'DES-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;

  const originalLineCount = invoice.lines.length;
  removeLine(invoice, 'DES-HOUR');

  assert.equal(invoice.lines.length, originalLineCount);
});

test('addLine and removeLine preserve invoice properties', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const afterAdd = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 }).value;
  assert.equal(afterAdd.customerId, 'C-001');
  assert.equal(afterAdd.issueDate, '2025-10-15');
  assert.equal(afterAdd.status, 'draft');

  const afterRemove = removeLine(afterAdd, 'DES-HOUR').value;
  assert.equal(afterRemove.customerId, 'C-001');
  assert.equal(afterRemove.issueDate, '2025-10-15');
  assert.equal(afterRemove.status, 'draft');
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2025-0001');
  assert.equal(result.value.status, 'issued');
});

test('issueInvoice calculates next number based on existing numbers', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const existing = ['INV-2025-0001', 'INV-2025-0002', 'INV-2025-0003'];
  const result = issueInvoice(invoice, existing);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2025-0004');
});

test('issueInvoice resets counter for a new year', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const existing = ['INV-2025-0001', 'INV-2025-0050', 'INV-2025-0100'];
  const result = issueInvoice(invoice, existing);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0001');
});

test('issueInvoice refuses to issue non-draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issuedInvoice = { ...invoice, status: 'issued', number: 'INV-2025-0001' };
  assert.deepEqual(issueInvoice(issuedInvoice, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice preserves all invoice properties', () => {
  const invoice = createInvoice({
    customerId: 'C-005',
    issueDate: '2025-06-30',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 8 },
    ],
  }).value;

  const result = issueInvoice(invoice, ['INV-2025-0001']).value;
  assert.equal(result.customerId, 'C-005');
  assert.equal(result.issueDate, '2025-06-30');
  assert.equal(result.lines.length, 2);
  assert.equal(result.lines[0].sku, 'DES-HOUR');
  assert.equal(result.lines[1].sku, 'DEV-HOUR');
});

test('issueInvoice does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.number, undefined);

  issueInvoice(invoice, []);

  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.number, undefined);
});

test('lineDiscount calculates discount from line total', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10 }; // €100 * 10% = €10
  assert.equal(lineDiscount(line), 1000);
});

test('lineDiscount handles decimal discount percentages', () => {
  const line = { qty: 4, unitPrice: 2500, discountPercent: 12.5 }; // €100 * 12.5% = €12.50
  assert.equal(lineDiscount(line), 1250);
});

test('lineDiscount returns 0 for line with no discount', () => {
  const line = { qty: 5, unitPrice: 8500 };
  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount returns 0 for 0% discount', () => {
  const line = { qty: 5, unitPrice: 8500, discountPercent: 0 };
  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount is clamped at 0', () => {
  const line = { qty: 1, unitPrice: 100, discountPercent: 100 };
  assert.equal(lineDiscount(line), 100);
});

test('invoiceTotals now includes discount and vat fields', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }], // €850 - €85 = €765, VAT €160.65
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 8500);
  assert.equal(totals.vat, 16065);
  assert.equal(totals.total, 92565);
});

test('invoiceTotals calculates total with multiple discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 }, // €850 - €85 = €765, VAT €160.65
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 20 },  // €475 - €95 = €380, VAT €79.80
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000 + 47500);
  assert.equal(totals.discount, 8500 + 9500);
  const expectedVAT = 16065 + 7980;
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, 132500 - 18000 + expectedVAT);
});

test('invoiceTotals total is clamped at 0', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 100 }], // Discount = 100%
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, 0);
});

test('createInvoice accepts discountPercent on lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 15 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 15);
});

test('createInvoice validates discountPercent range', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 101 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: -1 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice validates discountPercent is a number', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: '50' }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('addLine accepts discountPercent on new lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3, discountPercent: 20 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 20);
});

test('addLine validates discountPercent like createInvoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  assert.deepEqual(
    addLine(invoice, { sku: 'DEV-HOUR', qty: 1, discountPercent: 150 }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('addLine updates discountPercent when updating existing line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3, discountPercent: 20 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].qty, 8);
  assert.equal(result.value.lines[0].discountPercent, 20);
});

test('addLine preserves discountPercent when updating without specifying it', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 15 }],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].qty, 8);
  assert.equal(result.value.lines[0].discountPercent, 15);
});

test('TIER_DISCOUNTS exports the tier discount percentages', () => {
  assert.deepEqual(TIER_DISCOUNTS, {
    gold: 5,
    silver: 2.5,
    standard: 0,
  });
});

test('createInvoice applies gold tier discount to lines without discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001', // Northwind Studio, gold tier
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
});

test('createInvoice applies silver tier discount to lines without discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-003', // Kite & Co, silver tier
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
});

test('createInvoice does not add discountPercent for standard tier if it is 0', () => {
  const result = createInvoice({
    customerId: 'C-002', // Blue Fern Bakery, standard tier
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, undefined);
});

test('createInvoice line discountPercent overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier (5% automatic)
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10);
});

test('createInvoice explicit 0% discountPercent overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier (5% automatic)
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice applies tier discount to all lines without their own discount', () => {
  const result = createInvoice({
    customerId: 'C-003', // Kite & Co, silver tier (2.5%)
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // gets 2.5%
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 15 }, // overrides with 15%
      { sku: 'COPY-HOUR', qty: 2 }, // gets 2.5%
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
  assert.equal(result.value.lines[1].discountPercent, 15);
  assert.equal(result.value.lines[2].discountPercent, 2.5);
});

test('createInvoice tier discount affects invoiceTotals', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }], // €850 - 5% = €807.50
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 4250);
  assert.equal(totals.total, 80750);
});

test('createInvoice explicit discount overrides tier in totals', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }], // €850 - 10% = €765
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 8500);
  assert.equal(totals.total, 76500);
});

test('lineVAT calculates VAT on net amount after discount', () => {
  // Line: €850 with 5% discount = €807.50, VAT 21% = €169.575 ≈ €169.58
  const line = { qty: 10, unitPrice: 8500, discountPercent: 5, vatRate: 21 };
  const vat = lineVAT(line);
  assert.equal(vat, 16958);
});

test('lineVAT handles 9% VAT', () => {
  // Line: €37 with no discount, VAT 9% = €3.33
  const line = { qty: 100, unitPrice: 37, vatRate: 9 };
  const vat = lineVAT(line);
  assert.equal(vat, 333);
});

test('lineVAT handles 0% VAT (exempt)', () => {
  const line = { qty: 1, unitPrice: 60000, vatRate: 0 };
  const vat = lineVAT(line);
  assert.equal(vat, 0);
});

test('lineVAT returns 0 for line with no discount and 0% VAT', () => {
  const line = { qty: 5, unitPrice: 8500, vatRate: 0 };
  assert.equal(lineVAT(line), 0);
});

test('lineVAT is clamped at 0', () => {
  const line = { qty: 1, unitPrice: 100, discountPercent: 100, vatRate: 21 };
  const vat = lineVAT(line);
  assert.equal(vat, 0);
});

test('invoiceTotals now includes vat field', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }], // €850 * 21% = €178.50
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 17850);
  assert.equal(totals.total, 85000 + 17850);
});

test('invoiceTotals calculates VAT after discount per line', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 }, // €850 - €85 = €765, VAT €160.65
      { sku: 'PRINT-A4', qty: 100 }, // €37, VAT €3.33
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000 + 3700);
  assert.equal(totals.discount, 8500);
  const expectedVAT = 16065 + 333;
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, 88700 - 8500 + expectedVAT);
});

test('invoiceTotals total formula: subtotal - discount + vat', () => {
  const invoice = createInvoice({
    customerId: 'C-003', // silver tier (2.5%)
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // €425, discount 2.5% = €10.625, net €414.375, VAT €87.02
      { sku: 'LOGO-PACK', qty: 2, discountPercent: 10 }, // €2400, discount 10% = €240, net €2160, VAT €453.60
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 42500 + 240000;
  const expectedDiscount = 1063 + 24000; // rounded per line
  const expectedVAT = 8702 + 45360; // rounded per line
  const expectedTotal = expectedSubtotal - expectedDiscount + expectedVAT;

  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, expectedTotal);
});

test('invoiceTotals total is clamped at 0 after VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 100 }, // €600 - €600 = €0 + VAT (0%)
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, 0);
});

