test('renderInvoiceText shows all VAT-related lines in correct order', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Find the positions of subtotal, discount, VAT, and total
  const lastLineIdx = lines.length - 1;
  const totalIdx = lines.findIndex(l => l.startsWith('Total:'));
  const vatIdx = lines.findIndex(l => l.startsWith('VAT:'));
  const discountIdx = lines.findIndex(l => l.startsWith('Discount:'));
  const subtotalIdx = lines.findIndex(l => l.startsWith('Subtotal:'));

  // Verify order: Subtotal -> Discount -> VAT -> Total
  assert.ok(subtotalIdx < discountIdx);
  assert.ok(discountIdx < vatIdx);
  assert.ok(vatIdx < totalIdx);
});

